import{_ as e,a as o}from"./chunks/screenshot-client.BBcQFa0Y.js";import{_ as i,o as n,c as r,a1 as a}from"./chunks/framework.COskihg7.js";const f=JSON.parse('{"title":"Android App Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/android.md","filePath":"guide/android.md"}'),s={name:"guide/android.md"};function l(d,t,h,c,p,g){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="android-app-guide" tabindex="-1">Android App Guide <a class="header-anchor" href="#android-app-guide" aria-label="Permalink to &quot;Android App Guide&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Android app operates in two modes: <strong>Host</strong> (share your connection) and <strong>Client</strong> (connect to another host).</p><p><img src="'+e+'" alt="Hotspot Bypass VPN App"></p><hr><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Download the latest APK from the <a href="/Hotspot-Bypass-VPN-Unlimited-Hotspot/download">Download page</a>.</li><li>Open the APK file on your phone.</li><li>If prompted, enable <strong>Install from unknown sources</strong>.</li><li>Complete the installation.</li></ol><hr><h2 id="host-mode-share-your-connection" tabindex="-1">Host Mode (Share Your Connection) <a class="header-anchor" href="#host-mode-share-your-connection" aria-label="Permalink to &quot;Host Mode (Share Your Connection)&quot;">​</a></h2><p>Use this mode to share your phone&#39;s cellular data with other devices.</p><p><img src="'+e+'" alt="Host Mode Screenshot"><em>Host mode showing connection information</em></p><h3 id="step-1-grant-permissions" tabindex="-1">Step 1: Grant Permissions <a class="header-anchor" href="#step-1-grant-permissions" aria-label="Permalink to &quot;Step 1: Grant Permissions&quot;">​</a></h3><p>When you first tap <strong>Start Host</strong>, the app will request:</p><ul><li><strong>Location permission</strong> — Required by Android for Wi-Fi Direct discovery</li><li><strong>Notification permission</strong> — Required for foreground service</li><li><strong>Battery optimization ignore</strong> — Prevents the system from killing the service</li></ul><p>Grant all permissions for the best experience.</p><h3 id="step-2-configure-settings" tabindex="-1">Step 2: Configure Settings <a class="header-anchor" href="#step-2-configure-settings" aria-label="Permalink to &quot;Step 2: Configure Settings&quot;">​</a></h3><p>Before starting, you can configure:</p><ul><li><strong>Wi-Fi Band</strong> — Choose 2.4GHz (better range) or 5GHz (lower latency, recommended for gaming)</li><li>Check that <strong>Private DNS</strong> is set to <strong>Off</strong> or <strong>Automatic</strong> (not a custom DNS provider)</li></ul><h3 id="step-3-start-hosting" tabindex="-1">Step 3: Start Hosting <a class="header-anchor" href="#step-3-start-hosting" aria-label="Permalink to &quot;Step 3: Start Hosting&quot;">​</a></h3><ol><li>Tap the <strong>HOST</strong> tab at the top.</li><li>Tap <strong>Start Host</strong>.</li><li>A notification will appear: <strong>&quot;Hotspot Bypass Host&quot;</strong> — this confirms the service is running.</li><li>The screen will display connection details: <ul><li><strong>SSID:</strong> <code>DIRECT-HotspotBypass</code></li><li><strong>Password:</strong> <code>87654321</code></li><li><strong>Proxy IP:</strong> <code>192.168.49.1</code></li><li><strong>Proxy Port:</strong> <code>8080</code></li></ul></li><li>Tap the <strong>copy icons</strong> next to each field to share with clients.</li></ol><h3 id="step-4-client-devices-connect" tabindex="-1">Step 4: Client Devices Connect <a class="header-anchor" href="#step-4-client-devices-connect" aria-label="Permalink to &quot;Step 4: Client Devices Connect&quot;">​</a></h3><p>Tell your clients to:</p><ol><li>Open Wi-Fi settings on their device.</li><li>Connect to the network <strong>DIRECT-HotspotBypass</strong>.</li><li>Enter password <strong>87654321</strong>.</li><li>Configure their device or app to use the SOCKS5 proxy at <code>192.168.49.1:8080</code>.</li></ol><hr><h2 id="client-mode-connect-to-a-host" tabindex="-1">Client Mode (Connect to a Host) <a class="header-anchor" href="#client-mode-connect-to-a-host" aria-label="Permalink to &quot;Client Mode (Connect to a Host)&quot;">​</a></h2><p>Use this mode when another phone is running in Host mode.</p><p><img src="'+o+'" alt="Client Mode Screenshot"><em>Client mode showing VPN connected status</em></p><h3 id="step-1-grant-permissions-1" tabindex="-1">Step 1: Grant Permissions <a class="header-anchor" href="#step-1-grant-permissions-1" aria-label="Permalink to &quot;Step 1: Grant Permissions&quot;">​</a></h3><p>Similar to Host mode, the app will request location, notification, and battery optimization permissions.</p><h3 id="step-2-connect" tabindex="-1">Step 2: Connect <a class="header-anchor" href="#step-2-connect" aria-label="Permalink to &quot;Step 2: Connect&quot;">​</a></h3><ol><li>Tap the <strong>CLIENT</strong> tab at the top.</li><li>Tap <strong>Start Client</strong>.</li><li>The app will: <ul><li>Scan for Wi-Fi Direct networks</li><li>Connect to the Host&#39;s network</li><li>Start a local VPN that tunnels all traffic through the Host&#39;s SOCKS5 proxy</li></ul></li><li>A VPN notification will appear: <strong>&quot;Hotspot Bypass VPN&quot;</strong></li></ol><h3 id="step-3-verify" tabindex="-1">Step 3: Verify <a class="header-anchor" href="#step-3-verify" aria-label="Permalink to &quot;Step 3: Verify&quot;">​</a></h3><ul><li>Open a browser — your traffic should now be routed through the Host&#39;s connection.</li><li>Check the debug log (expandable at the bottom of the screen) for connection status.</li></ul><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Issue</th><th>Solution</th></tr></thead><tbody><tr><td>Can&#39;t find Host network</td><td>Make sure both devices have Wi-Fi Direct enabled. Try toggling Wi-Fi off/on.</td></tr><tr><td>VPN connection fails</td><td>Tap <strong>Reconnect VPN</strong> button. If it persists, restart the app.</td></tr><tr><td>Slow speeds</td><td>Try switching to 5GHz band on the Host side. Ensure good signal between devices.</td></tr><tr><td>Private DNS warning</td><td>Go to Settings → Network &amp; Internet → Private DNS → set to <strong>Off</strong> or <strong>Automatic</strong>.</td></tr><tr><td>Service stops after screen off</td><td>Grant <strong>Ignore battery optimization</strong> permission to the app.</td></tr><tr><td>Connection drops</td><td>Both devices should stay within Wi-Fi Direct range (typically 30-50 meters).</td></tr></tbody></table><hr><h2 id="debug-log" tabindex="-1">Debug Log <a class="header-anchor" href="#debug-log" aria-label="Permalink to &quot;Debug Log&quot;">​</a></h2><p>The app includes a built-in debug log viewer at the bottom of the screen. Tap it to expand and view real-time diagnostic information. This is useful for troubleshooting connection issues.</p>',38)])])}const b=i(s,[["render",l]]);export{f as __pageData,b as default};
